def write(path,text):
 p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def write_json(path,data): write(path,json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def variants(src,key):
 im=Image.open(src).convert('RGB'); ratio=1.5
 if im.width/im.height>ratio:
  w=round(im.height*ratio); x=(im.width-w)//2; im=im.crop((x,0,x+w,im.height))
 else:
  h=round(im.width/ratio); y=(im.height-h)//2; im=im.crop((0,y,im.width,y+h))
 out=ROOT/'assets/images/editorial-auto'; out.mkdir(parents=True,exist_ok=True); result=[]
 for w in (480,800,1200):
  p=out/f'{key}-{w}.webp'; im.resize((w,round(w*2/3)),Image.Resampling.LANCZOS).save(p,'WEBP',quality=86,method=6)
  result.append({'w':w,'src':f'/assets/images/editorial-auto/{p.name}','sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size})
 return result

