 dt=datetime(2026,9,20,0,20,tzinfo=ZoneInfo('Europe/Rome')); qurl=f'/domanda-del-giorno/{QSLUG}/'; burl=f'/biblioteca/vita-relazioni/domande-per-conoscersi/{QSLUG}/'
