 write_json(Path('automation/logs/editoriale-20260920T002000-Europe-Rome.json'),{'run_at':STAMP,'processed':[{'title':a['titolo'],'decision':'publish'} for a in NEWS],'daily_question':{'number':452,'question':QUESTION},'guides':['Come usare VPN gratis','Come cambiare DNS']})
